<?php
require __DIR__ . '/app.php'; $code=strtoupper(trim($_GET['ticket']??'')); $ticket=null; $error='';
if($code!=='') { try { $stmt=db()->prepare('SELECT ticket_code,building,floor,status,admin_note,created_at,updated_at FROM repair_tickets WHERE ticket_code=?');$stmt->bind_param('s',$code);$stmt->execute();$ticket=$stmt->get_result()->fetch_assoc();$stmt->close(); } catch(Throwable $e) {$error='เชื่อมต่อฐานข้อมูลไม่ได้ กรุณาลองอีกครั้ง';} }
page_head('ติดตามงานซ่อม','track'); ?>
<section class="track-hero"><p class="eyebrow">TRACK YOUR REPAIR</p><h1>ติดตามสถานะงาน</h1><p>กรอก Ticket ที่ได้รับหลังแจ้งซ่อม เพื่อดูความคืบหน้าล่าสุด</p><form class="track-search" method="get"><span>⌕</span><input name="ticket" value="<?=e($code)?>" required maxlength="11" placeholder="RIETC-XXXXX"><button class="button">ค้นหา Ticket <b>→</b></button></form></section>
